PRAGMA foreign_keys=ON;
CREATE TABLE churches (id TEXT PRIMARY KEY, name TEXT NOT NULL, subDomain TEXT NOT NULL UNIQUE, settings TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(settings)), createdAt TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, firstName TEXT NOT NULL, lastName TEXT NOT NULL, passwordHash TEXT NOT NULL, disabled INTEGER NOT NULL DEFAULT 0 CHECK(disabled IN (0,1)));
CREATE TABLE households (id TEXT PRIMARY KEY, churchId TEXT NOT NULL REFERENCES churches(id), name TEXT NOT NULL, UNIQUE(churchId,id));
CREATE TABLE people (id TEXT PRIMARY KEY, churchId TEXT NOT NULL REFERENCES churches(id), firstName TEXT NOT NULL, lastName TEXT NOT NULL, middleName TEXT NOT NULL DEFAULT '', nickName TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', contactInfo TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(contactInfo)), birthDate TEXT, gender TEXT, maritalStatus TEXT, anniversary TEXT, membershipStatus TEXT NOT NULL DEFAULT 'Visitor', grade TEXT, school TEXT, householdId TEXT, householdRole TEXT, campusId TEXT, photo TEXT, dateAdded TEXT NOT NULL, directoryVisible INTEGER NOT NULL DEFAULT 0 CHECK(directoryVisible IN (0,1)), shareEmail INTEGER NOT NULL DEFAULT 0 CHECK(shareEmail IN (0,1)), removed INTEGER NOT NULL DEFAULT 0 CHECK(removed IN (0,1)), UNIQUE(churchId,id), FOREIGN KEY(churchId,householdId) REFERENCES households(churchId,id));
CREATE INDEX people_tenant_name ON people(churchId,removed,lastName,firstName);
CREATE INDEX people_tenant_household ON people(churchId,householdId);
CREATE TABLE user_churches (userId TEXT NOT NULL REFERENCES users(id), churchId TEXT NOT NULL REFERENCES churches(id), personId TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','viewer','member')), PRIMARY KEY(userId,churchId), FOREIGN KEY(churchId,personId) REFERENCES people(churchId,id));
CREATE TABLE groups (id TEXT PRIMARY KEY, churchId TEXT NOT NULL REFERENCES churches(id), name TEXT NOT NULL, categoryName TEXT NOT NULL DEFAULT '', tags TEXT NOT NULL DEFAULT 'standard', joinPolicy TEXT NOT NULL DEFAULT 'closed' CHECK(joinPolicy IN ('open','request','closed')), trackAttendance INTEGER NOT NULL DEFAULT 0 CHECK(trackAttendance IN (0,1)), parentId TEXT, label TEXT, about TEXT, UNIQUE(churchId,id), FOREIGN KEY(churchId,parentId) REFERENCES groups(churchId,id));
CREATE INDEX groups_tenant ON groups(churchId,name);
CREATE TABLE group_members (id TEXT PRIMARY KEY, churchId TEXT NOT NULL REFERENCES churches(id), groupId TEXT NOT NULL, personId TEXT NOT NULL, leader INTEGER NOT NULL DEFAULT 0 CHECK(leader IN (0,1)), UNIQUE(churchId,groupId,personId), FOREIGN KEY(churchId,personId) REFERENCES people(churchId,id), FOREIGN KEY(churchId,groupId) REFERENCES groups(churchId,id) ON DELETE CASCADE);
CREATE TABLE sessions (id TEXT PRIMARY KEY, userId TEXT NOT NULL REFERENCES users(id), expiresAt TEXT NOT NULL, createdAt TEXT NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expiresAt);
CREATE TABLE auth_attempts (id TEXT PRIMARY KEY, attempts INTEGER NOT NULL, expiresAt TEXT NOT NULL);
CREATE TABLE audit_log (id TEXT PRIMARY KEY, churchId TEXT NOT NULL REFERENCES churches(id), userId TEXT NOT NULL, action TEXT NOT NULL, entityId TEXT NOT NULL, createdAt TEXT NOT NULL);
CREATE INDEX audit_tenant_time ON audit_log(churchId,createdAt);
